/**
 * Resolves a field key-or-id to its hex field id within one workflow's
 * field map. Matches the createFieldResolver convention in
 * apps/starting-eleven/src/hailer/field-resolver.ts.
 */
export function createFieldResolver(workflowFields: Record<string, { id: string }>) {
    const keyToId: Record<string, string> = {};
    for (const [key, field] of Object.entries(workflowFields)) {
        keyToId[key] = field.id;
    }
    return (keyOrId: string): string => keyToId[keyOrId] ?? keyOrId;
}
